ALTER TABLE public.community_posts ADD COLUMN title text NOT NULL DEFAULT '' CHECK (char_length(title)<=120);
GRANT SELECT(title) ON public.community_posts TO anon,authenticated;
ALTER TABLE public.community_reports ADD COLUMN comment_id uuid, ADD COLUMN media_id uuid, ADD COLUMN target_type text NOT NULL DEFAULT 'post' CHECK (target_type IN ('post','comment','image','video'));
CREATE TABLE public.community_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.community_posts(id) ON DELETE CASCADE, image_path text NOT NULL, position integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','hidden','rejected')), created_at timestamptz NOT NULL DEFAULT now(), moderation_note text);
GRANT ALL ON public.community_media TO service_role;
ALTER TABLE public.community_media ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.community_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.community_posts(id) ON DELETE CASCADE, parent_id uuid REFERENCES public.community_comments(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Anonim' CHECK (char_length(display_name) BETWEEN 1 AND 40), message text NOT NULL CHECK (char_length(message) BETWEEN 2 AND 1000), member_label text CHECK (member_label IN ('hasta','hasta_yakini')), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','hidden','rejected')), created_at timestamptz NOT NULL DEFAULT now(), moderation_note text);
GRANT ALL ON public.community_comments TO service_role;
ALTER TABLE public.community_comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_reports ADD CONSTRAINT community_report_comment_fk FOREIGN KEY(comment_id) REFERENCES public.community_comments(id) ON DELETE CASCADE;
ALTER TABLE public.community_reports ADD CONSTRAINT community_report_media_fk FOREIGN KEY(media_id) REFERENCES public.community_media(id) ON DELETE CASCADE;
CREATE INDEX community_comments_post_idx ON public.community_comments(post_id,created_at);
CREATE INDEX community_media_post_idx ON public.community_media(post_id,position);
CREATE OR REPLACE VIEW public.community_public_posts WITH (security_barrier=true) AS SELECT id,display_name,message,member_label,created_at,image_path,image_status,CASE WHEN video_status='approved' THEN video_url ELSE NULL END AS video_url,CASE WHEN video_status='approved' THEN 'approved' ELSE NULL END AS video_status,title FROM public.community_posts WHERE status='approved';
CREATE VIEW public.community_public_media WITH (security_barrier=true) AS SELECT m.id,m.post_id,m.position FROM public.community_media m JOIN public.community_posts p ON p.id=m.post_id WHERE m.status='approved' AND p.status='approved';
GRANT SELECT ON public.community_public_media TO anon,authenticated,service_role;
CREATE VIEW public.community_public_comments WITH (security_barrier=true) AS WITH RECURSIVE visible AS (SELECT c.id,c.post_id,c.parent_id,c.display_name,c.message,c.member_label,c.created_at,0 AS depth FROM public.community_comments c JOIN public.community_posts p ON p.id=c.post_id WHERE c.status='approved' AND c.parent_id IS NULL AND p.status='approved' UNION ALL SELECT c.id,c.post_id,c.parent_id,c.display_name,c.message,c.member_label,c.created_at,v.depth+1 FROM public.community_comments c JOIN visible v ON c.parent_id=v.id AND c.post_id=v.post_id WHERE c.status='approved' AND v.depth<5) SELECT id,post_id,parent_id,display_name,message,member_label,created_at,depth FROM visible;
GRANT SELECT ON public.community_public_comments TO anon,authenticated,service_role;
CREATE FUNCTION public.validate_community_comment_parent() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE parent_post uuid; BEGIN IF NEW.parent_id IS NOT NULL THEN SELECT post_id INTO parent_post FROM public.community_comments WHERE id=NEW.parent_id; IF parent_post IS DISTINCT FROM NEW.post_id THEN RAISE EXCEPTION 'Reply must belong to the same story'; END IF; END IF; IF TG_OP='UPDATE' AND (NEW.parent_id IS DISTINCT FROM OLD.parent_id OR NEW.post_id IS DISTINCT FROM OLD.post_id) THEN RAISE EXCEPTION 'Reply ancestry is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_community_comment_parent BEFORE INSERT OR UPDATE ON public.community_comments FOR EACH ROW EXECUTE FUNCTION public.validate_community_comment_parent();
CREATE VIEW public.community_comment_moderation_queue WITH (security_invoker=true) AS SELECT c.*, CASE WHEN EXISTS(SELECT 1 FROM public.community_reports r WHERE r.comment_id=c.id AND r.status='pending') THEN 'raporlanan' WHEN c.status='pending' THEN 'onay_bekleyen' WHEN c.status='approved' THEN 'yayinda' ELSE c.status END AS queue_status FROM public.community_comments c;
GRANT SELECT ON public.community_comment_moderation_queue TO service_role;
CREATE VIEW public.community_media_moderation_queue WITH (security_invoker=true) AS SELECT m.*, CASE WHEN EXISTS(SELECT 1 FROM public.community_reports r WHERE r.media_id=m.id AND r.status='pending') THEN 'raporlanan' WHEN m.status='pending' THEN 'onay_bekleyen' WHEN m.status='approved' THEN 'yayinda' ELSE m.status END AS queue_status FROM public.community_media m;
GRANT SELECT ON public.community_media_moderation_queue TO service_role;
COMMENT ON TABLE public.community_comments IS 'Human-reviewed story conversations. Hiding/deleting an ancestor hides/removes its descendants. Public view excludes every unapproved branch.';
COMMENT ON TABLE public.community_media IS 'Human-reviewed story photos, independently approve/hide/delete each image. Private Storage objects are never publicly readable.';
